145→func TestRun_AppliesTimeoutWhenNoDeadline(t *testing.T) {
146→	// Not parallel: mutates package-level defaultRunTimeout.
147→	if _, err := exec.LookPath("sh"); err != nil {
148→		t.Skip("sh not available")
149→	}
150→
151→	script := `#!/bin/sh
152→case "$1" in
153→  info)
154→    echo '` + validInfoJSON + `'
155→    ;;
156→  slow)
157→    exec sleep 60
158→    ;;
159→esac
160→`
161→	binPath := testBinaryDir(t, script)
162→	ea := newExternalAgent(t, binPath)
163→
164→	// Temporarily override the default timeout to keep the test fast.
165→	orig := defaultRunTimeout
166→	defaultRunTimeout = 1 * time.Second
167→	t.Cleanup(func() { defaultRunTimeout = orig })
168→
169→	start := time.Now()
170→	_, err := ea.run(context.Background(), nil, "slow")
171→	elapsed := time.Since(start)
172→
173→	if err == nil {
174→		t.Fatal("expected timeout error, got nil")
175→	}
176→	// Should be killed around 1s, not 60s.
177→	if elapsed >= 5*time.Second {
178→		t.Errorf("run() took %v; default timeout was not applied", elapsed)
179→	}
180→}
